  world=Fixture(22,4);var python=world.Actors.Single(a=>a.Name=="Mutated Python");check(python.MaxHp==45&&python.Ac==14&&python.EffectiveSpeedFeet==30,"Phase 26 mutated python retains its detailed printed stat block");
  world=Fixture(29);Clear(world);check(Do(world,"upper26-back"),"Phase 26 Final Boss is physically released through stockroom investigation");var boss=world.Actors.Single(a=>a.Name=="Final Boss");world.ResolveCampaignHazard(boss,21,DamageType.Piercing);state=world.LowerMallProgress(129)!;int released=state.Releases.Sum(r=>r.Count);check(state.Events.Contains("boss-roar")&&world.Actors.Any(a=>a.Alive&&a.Name.StartsWith("Glitched Zombie")),"Phase 26 Final Boss half-HP threshold releases its finite reinforcement pool");world.ResolveCampaignHazard(boss,1,DamageType.Piercing);check(state.Releases.Sum(r=>r.Count)==released,"Phase 26 Respawn Roar cannot repeat below half HP");
  world=Fixture(30);var glitcher=world.Actors.First(a=>a.Name.StartsWith("Glitcher"));hero=world.PartyLeader;check(world.AttackModifiers(hero,glitcher).Disadvantage&&Do(world,"upper26-observe")&&!world.AttackModifiers(hero,glitcher).Disadvantage,"Phase 26 observing the glitch pattern removes the actual attack disadvantage");check(Do(world,"upper26-power")&&world.LowerMallProgress(130)!.Events.Contains("power-cut"),"Phase 26 retro-shop power isolation is a saved mechanical outcome");
